import { test } from 'node:test';
import assert from 'node:assert/strict';
import { mkdirSync, mkdtempSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { runPlugin, pluginPath, REFUSED } from '../src/launcher.mjs';

const root = process.cwd();

function captureStderr(fn) {
  const original = process.stderr.write.bind(process.stderr);
  let captured = '';
  process.stderr.write = (chunk) => {
    captured += chunk;
    return true;
  };
  try {
    return { result: fn(), stderr: captured };
  } finally {
    process.stderr.write = original;
  }
}

test('a working plugin runs and its exit code is 0', () => {
  assert.equal(runPlugin(root, 'hello'), 0);
});

test("a failing plugin's own exit code is propagated", () => {
  assert.equal(runPlugin(root, 'fails'), 7);
});

test('a plugin that does not exist is refused', () => {
  assert.equal(runPlugin(root, 'absent'), REFUSED);
});

test('a plugin path that is a directory is refused, naming the plugin, without starting it', () => {
  const scratch = mkdtempSync(join(tmpdir(), 'launcher-test-'));
  try {
    mkdirSync(pluginPath(scratch, 'dir-plugin'));
    const { result, stderr } = captureStderr(() => runPlugin(scratch, 'dir-plugin'));
    assert.equal(result, REFUSED);
    assert.match(stderr, /dir-plugin/);
  } finally {
    rmSync(scratch, { recursive: true, force: true });
  }
});

test('an unreadable plugin file is refused, naming the plugin, without starting it', () => {
  const scratch = mkdtempSync(join(tmpdir(), 'launcher-test-'));
  try {
    const script = pluginPath(scratch, 'locked-plugin');
    writeFileSync(script, '#!/bin/bash\necho "should never run" > "$0.ran"\nexit 0\n');
    try {
      require('node:fs').chmodSync(script, 0o000);
    } catch {
      // Some environments (e.g. running as root) can't remove read access;
      // skip the assertion body but don't fail the suite for that reason.
    }
    const { result, stderr } = captureStderr(() => runPlugin(scratch, 'locked-plugin'));
    assert.equal(result, REFUSED);
    assert.match(stderr, /locked-plugin/);
  } finally {
    rmSync(scratch, { recursive: true, force: true });
  }
});

